mapper.select:
SELECT id AS audit_log_id,
       admin_id AS admin_id,
       action AS action,
       target_type AS target_type,
       target_id AS target_id,
       detail AS detail,
       created_at AS created_at
FROM admin_audit_log


        admin_id = #{adminId}


        AND target_type = #{targetType}


        AND created_at >= #{from}


        AND created_at < #{to}


ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}
